// The announcement banner. The admin writes it in the dashboard (Site content tab): words, an optional link, a colour and an end time.
// It sits just under the menu bar, scrolls away with the page, and a visitor can close it (it stays closed until the words change).
// Nothing shows (and nothing is downloaded) while no banner is switched on. You do not edit this file.
import { useState } from 'react';
import { Link } from 'react-router-dom';
import { liveValue, useLiveSettings } from './liveSettings';
import './SiteBanner.css';

// the Indian time now as 'YYYY-MM-DDTHH:MM' (text compares in the right order)
const istNow = () => new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 16);

const hashOf = (s) => { let h = 5381; for (let i = 0; i < s.length; i += 1) h = ((h << 5) + h + s.charCodeAt(i)) | 0; return (h >>> 0).toString(36); };
const closedKey = (b) => `scc-banner-x-${hashOf(`${b.text}|${b.link}|${b.until}`)}`;
const wasClosed = (b) => { try { return window.sessionStorage.getItem(closedKey(b)) === '1'; } catch { return false; } };

/* the pill itself. `preview` = drawn inside the dashboard (no position, no close button) */
export function BannerPill({ b, onClose, preview }) {
  const label = b.linkText || 'Learn more';
  const link = b.link
    ? (b.link.startsWith('/')
      ? <Link className="sb-link" to={b.link}>{label}</Link>
      : <a className="sb-link" href={b.link} target="_blank" rel="noopener noreferrer">{label}</a>)
    : null;
  return (
    <div className={`sb-pill sb-${b.tone || 'info'} ${preview ? 'is-preview' : ''}`} role={preview ? undefined : 'status'}>
      <span className="sb-dot" aria-hidden="true" />
      <span className="sb-text">{b.text || 'Your announcement will appear here.'}</span>
      {link}
      {!preview && <button type="button" className="sb-x" aria-label="Close announcement" onClick={onClose}>&times;</button>}
    </div>
  );
}

export default function SiteBanner() {
  useLiveSettings();
  const b = liveValue('banner', null);
  const [, bump] = useState(0);
  if (!b || typeof b !== 'object' || b.on !== true || !b.text) return null;
  if (b.until && istNow() >= b.until) return null;
  if (wasClosed(b)) return null;
  const close = () => { try { window.sessionStorage.setItem(closedKey(b), '1'); } catch { /* private mode: it just comes back on the next page */ } bump((n) => n + 1); };
  return (
    <div className="sb-wrap">
      <BannerPill b={b} onClose={close} />
    </div>
  );
}
